create extension if not exists pgcrypto;
create type public.portal_role as enum ('requester','staff','admin');
create type public.pole_status as enum ('active','retired');
create type public.report_status as enum ('submitted','reviewing','assigned','in_repair','closed','reopened','merged');
create type public.report_severity as enum ('low','normal','urgent');
create table public.wards(id uuid primary key default gen_random_uuid(), name text not null unique, code text not null unique, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(length(display_name) between 1 and 120), role public.portal_role not null default 'requester', ward_id uuid references public.wards(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.poles(id uuid primary key default gen_random_uuid(), asset_tag text not null unique, ward_id uuid not null references public.wards(id), location_note text not null check(length(location_note) between 4 and 180), latitude double precision check(latitude between -90 and 90), longitude double precision check(longitude between -180 and 180), status public.pole_status not null default 'active', installed_at date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((latitude is null)=(longitude is null)));
create table public.reports(id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id), pole_id uuid references public.poles(id), ward_id uuid not null references public.wards(id), location_note text not null check(length(location_note) between 4 and 180), description text not null check(length(description) between 10 and 1200), severity public.report_severity not null default 'normal', status public.report_status not null default 'submitted', assigned_to uuid references public.profiles(id), duplicate_of uuid references public.reports(id), merged_into uuid references public.reports(id), repair_outcome text check(repair_outcome is null or length(repair_outcome)<=800), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), closed_at timestamptz, check(merged_into is null or merged_into<>id));
create table public.report_events(id bigint generated always as identity primary key, report_id uuid not null references public.reports(id) on delete cascade, actor_id uuid references public.profiles(id), event_type text not null check(event_type in ('created','status_changed','assigned','merged','evidence_added','reopened')), from_status public.report_status, to_status public.report_status, note text check(note is null or length(note)<=800), created_at timestamptz not null default now());
create table public.repair_evidence(id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete cascade, uploaded_by uuid not null references public.profiles(id), description text not null check(length(description) between 5 and 500), file_url text, created_at timestamptz not null default now());
create index reports_ward_status_created on public.reports(ward_id,status,created_at desc);
create index reports_pole_created on public.reports(pole_id,created_at desc) where pole_id is not null;
create index reports_reporter_created on public.reports(reporter_id,created_at desc);
create index reports_assigned_status on public.reports(assigned_to,status);
create index events_report_created on public.report_events(report_id,created_at desc);
create index poles_ward_status on public.poles(ward_id,status);
create or replace function public.record_report_event() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into report_events(report_id,actor_id,event_type,to_status,note) values(new.id,new.reporter_id,'created',new.status,'Report received'); return new; end if; if old.status is distinct from new.status then insert into report_events(report_id,actor_id,event_type,from_status,to_status,note) values(new.id,coalesce(nullif(current_setting('app.actor_id',true),'' )::uuid,auth.uid()),case when new.status='reopened' then 'reopened' else 'status_changed' end,old.status,new.status,coalesce(nullif(current_setting('app.event_note',true),''),new.repair_outcome)); end if; if old.assigned_to is distinct from new.assigned_to and new.assigned_to is not null then insert into report_events(report_id,actor_id,event_type,note) values(new.id,coalesce(nullif(current_setting('app.actor_id',true),'' )::uuid,auth.uid()),'assigned','Work assigned'); end if; return new; end $$;
create trigger reports_event_trigger after insert or update on public.reports for each row execute function public.record_report_event();
create or replace function public.transition_report(p_report_id uuid,p_status public.report_status,p_note text,p_assigned_to uuid,p_repair_outcome text,p_actor uuid) returns public.reports language plpgsql security definer set search_path=public as $$ declare r public.reports; allowed boolean; begin perform set_config('app.actor_id',p_actor::text,true); perform set_config('app.event_note',coalesce(p_note,''),true); select * into r from reports where id=p_report_id for update; if not found then raise exception 'Report not found'; end if; allowed := (r.status='submitted' and p_status='reviewing') or (r.status='reviewing' and p_status='assigned') or (r.status='assigned' and p_status='in_repair') or (r.status='in_repair' and p_status='closed') or (r.status='closed' and p_status='reopened') or (r.status='reopened' and p_status in ('reviewing','assigned')); if not allowed then raise exception 'Invalid report status transition'; end if; if p_status='assigned' and coalesce(p_assigned_to,r.assigned_to) is null then raise exception 'Assignment is required'; end if; if p_status='assigned' and not exists(select 1 from profiles a where a.id=coalesce(p_assigned_to,r.assigned_to) and a.role in ('staff','admin') and (a.role='admin' or a.ward_id=r.ward_id)) then raise exception 'Assignee must be staff scoped to this ward'; end if; if p_status='closed' and nullif(trim(p_repair_outcome),'') is null then raise exception 'Repair outcome is required to close'; end if; update reports set status=p_status, assigned_to=coalesce(p_assigned_to,assigned_to), repair_outcome=coalesce(p_repair_outcome,repair_outcome), closed_at=case when p_status='closed' then now() when p_status='reopened' then null else closed_at end, updated_at=now() where id=p_report_id returning * into r; return r; end $$;
create or replace function public.merge_reports(p_source_id uuid,p_target_id uuid,p_note text,p_actor uuid) returns public.reports language plpgsql security definer set search_path=public as $$ declare s public.reports; t public.reports; old_status public.report_status; begin perform set_config('app.actor_id',p_actor::text,true); perform set_config('app.event_note',coalesce(p_note,''),true); if p_source_id=p_target_id then raise exception 'Cannot merge a report into itself'; end if; select * into s from reports where id=p_source_id for update; select * into t from reports where id=p_target_id for update; if s.id is null or t.id is null then raise exception 'Report not found'; end if; if s.status not in ('submitted','reviewing','assigned','in_repair','reopened') or t.status not in ('submitted','reviewing','assigned','in_repair','reopened') then raise exception 'Only open reports can be merged'; end if; if s.ward_id<>t.ward_id or (s.pole_id is not null and t.pole_id is not null and s.pole_id<>t.pole_id) then raise exception 'Reports must refer to the same ward and compatible pole'; end if; old_status:=s.status; update reports set status='merged', merged_into=p_target_id, duplicate_of=p_target_id, updated_at=now() where id=p_source_id returning * into s; insert into report_events(report_id,actor_id,event_type,from_status,to_status,note) values(p_source_id,p_actor,'merged',old_status,'merged',p_note); return s; end $$;
-- RLS is enabled on every exposed table. Reads are limited to public catalogue data or a user's own records; staff may read operational reports within their ward. Mutations are performed through the API service layer and narrowly defined RPCs.
alter table wards enable row level security; alter table profiles enable row level security; alter table poles enable row level security; alter table reports enable row level security; alter table report_events enable row level security; alter table repair_evidence enable row level security;
create policy wards_public_read on wards for select using (true);
create policy poles_public_read on poles for select using (status='active');
create policy profiles_self_read on profiles for select using (id=auth.uid());
create policy reports_owner_read on reports for select using (reporter_id=auth.uid());
create policy reports_staff_read on reports for select using (exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('staff','admin') and (p.role='admin' or p.ward_id=reports.ward_id)));
create policy events_owner_read on report_events for select using (exists(select 1 from reports r where r.id=report_id and (r.reporter_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('staff','admin') and (p.role='admin' or p.ward_id=r.ward_id)))));
create policy evidence_owner_read on repair_evidence for select using (exists(select 1 from reports r where r.id=report_id and (r.reporter_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role in ('staff','admin') and (p.role='admin' or p.ward_id=r.ward_id)))));
revoke all on function public.transition_report(uuid,public.report_status,text,uuid,text,uuid) from public,anon,authenticated;
revoke all on function public.merge_reports(uuid,uuid,text,uuid) from public,anon,authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,role) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(coalesce(new.email,'resident'),'@',1)),'requester'); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
-- Supabase REST roles need explicit read grants; RLS policies below constrain these reads.
grant select on public.wards,public.poles,public.profiles,public.reports,public.report_events,public.repair_evidence to anon,authenticated;
grant execute on function public.transition_report(uuid,public.report_status,text,uuid,text,uuid) to service_role;
grant execute on function public.merge_reports(uuid,uuid,text,uuid) to service_role;
